// ⚠ BROKEN — demonstrates data corruption with shared mutable state
package com.bank.safepipe.service;

import com.bank.safepipe.dto.PipelineResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.stream.IntStream;

@Service
@Slf4j
public class UnsafeService {

    // ═══ SHARED ARRAYLIST + PARALLEL = DATA CORRUPTION ═══
    public PipelineResult demonstrateCorruption() {
        int totalElements = 10_000;

        // ❌ WRONG: shared mutable ArrayList
        List<String> results = new ArrayList<>();

        try {
            IntStream.rangeClosed(1, totalElements)
                .parallel()  // multiple ForkJoinPool threads!
                .mapToObj(i -> "TRADE-" + String.format("%05d", i))
                .forEach(results::add);  // 💥 concurrent add to non-thread-safe list!
        } catch (ArrayIndexOutOfBoundsException e) {
            log.error("💥 ArrayIndexOutOfBoundsException! ArrayList internal array corrupted");
            return new PipelineResult("UNSAFE (shared ArrayList + parallel)",
                totalElements, results.size(), true,
                results.stream().limit(5).toList(),
                "ArrayIndexOutOfBoundsException — ArrayList internal array was resized " +
                "concurrently by multiple threads!");
        }

        boolean loss = results.size() < totalElements;
        log.warn("⚠ Expected {} entries, got {} — {} entries {}!",
            totalElements, results.size(),
            totalElements - results.size(), loss ? "LOST" : "OK");

        return new PipelineResult("UNSAFE (shared ArrayList + parallel)",
            totalElements, results.size(), loss,
            results.stream().limit(5).toList(),
            loss ? "DATA LOSS: " + (totalElements - results.size()) + " entries lost in race condition!"
                 : "Got lucky this time — but still unsafe code!");
    }

    // ═══ SIDE EFFECT IN MAP — UNPREDICTABLE ORDER ═══
    public PipelineResult demonstrateSideEffectInMap() {
        List<String> auditLog = Collections.synchronizedList(new ArrayList<>());

        List<String> result = IntStream.rangeClosed(1, 100)
            .parallel()
            .mapToObj(i -> {
                auditLog.add("processed: " + i);  // side effect inside map!
                return "TRADE-" + i;
            })
            .toList();

        // auditLog order is SCRAMBLED in parallel:
        boolean ordered = true;
        for (int i = 1; i < auditLog.size(); i++) {
            int prev = Integer.parseInt(auditLog.get(i - 1).replace("processed: ", ""));
            int curr = Integer.parseInt(auditLog.get(i).replace("processed: ", ""));
            if (curr < prev) { ordered = false; break; }
        }

        return new PipelineResult("SIDE_EFFECT_IN_MAP (synchronized but scrambled)",
            100, result.size(), false,
            auditLog.stream().limit(10).toList(),
            "Even with synchronizedList, order is scrambled in parallel: " +
            (ordered ? "happened to be ordered" : "ORDER IS WRONG — unpredictable!"));
    }
}
