// ✅ CORRECT — collect/reduce, no shared mutable state
package com.bank.safepipe.service;

import com.bank.safepipe.dto.PipelineResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

@Service
@Slf4j
public class SafeService {

    // ═══ COLLECT — thread-safe by design ═══
    public PipelineResult demonstrateSafeCollect() {
        int totalElements = 10_000;

        // ✅ CORRECT: collect() handles thread-local accumulation + merge
        List<String> results = IntStream.rangeClosed(1, totalElements)
            .parallel()
            .mapToObj(i -> "TRADE-" + String.format("%05d", i))
            .collect(Collectors.toList());  // each thread has OWN list → merged

        boolean loss = results.size() < totalElements;

        log.info("✅ SAFE: Expected {}, got {} — ZERO data loss!", totalElements, results.size());

        return new PipelineResult("SAFE (collect — thread-local + merge)",
            totalElements, results.size(), loss,
            results.stream().limit(5).toList(),
            "collect(toList()): supplier=ArrayList::new per thread, " +
            "accumulator=add, combiner=addAll. Thread-safe by design!");
    }

    // ═══ REDUCE — also side-effect-free ═══
    public PipelineResult demonstrateSafeReduce() {
        int totalElements = 10_000;

        long sum = IntStream.rangeClosed(1, totalElements)
            .parallel()
            .reduce(0, Integer::sum);  // identity=0, thread-safe accumulation

        long expected = (long) totalElements * (totalElements + 1) / 2;
        boolean correct = sum == expected;

        return new PipelineResult("SAFE (reduce — associative operation)",
            totalElements, (int) sum, !correct,
            List.of("sum=" + sum, "expected=" + expected),
            "reduce(0, Integer::sum): each thread reduces its partition, " +
            "then partitions are combined. Associative + identity = correct in parallel.");
    }
}
