package com.bank.safepipe.service;

import org.junit.jupiter.api.RepeatedTest;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class SideEffectFreeTest {

    // ═══ PROOF: parallel + shared ArrayList = data loss ═══
    @RepeatedTest(3)
    void parallelForEachWithSharedListLosesData() {
        List<Integer> shared = new ArrayList<>();

        IntStream.rangeClosed(1, 10_000)
            .parallel()
            .forEach(shared::add);  // ❌ unsafe!

        // ArrayList might lose elements or throw exception
        // We can't assert exact count — it's non-deterministic
        // But collect() always works:
        List<Integer> safe = IntStream.rangeClosed(1, 10_000)
            .parallel()
            .boxed()
            .collect(Collectors.toList());

        assertThat(safe).hasSize(10_000);  // always correct!
        // shared.size() is often < 10_000
    }

    // ═══ CORRECT: collect is always safe ═══
    @Test
    void collectIsAlwaysSafe() {
        List<String> result = IntStream.rangeClosed(1, 10_000)
            .parallel()
            .mapToObj(i -> "T-" + i)
            .collect(Collectors.toList());

        assertThat(result).hasSize(10_000);  // always 10,000!
    }

    // ═══ CORRECT: reduce is always safe ═══
    @Test
    void reduceIsAlwaysSafe() {
        long sum = IntStream.rangeClosed(1, 1000)
            .parallel()
            .reduce(0, Integer::sum);

        assertThat(sum).isEqualTo(500_500);  // always correct!
    }

    // ═══ toList() (Java 16) is unmodifiable and safe ═══
    @Test
    void toListIsSafeAndUnmodifiable() {
        List<String> result = IntStream.rangeClosed(1, 100)
            .parallel()
            .mapToObj(i -> "T-" + i)
            .toList();

        assertThat(result).hasSize(100);
        assertThatThrownBy(() -> result.add("X"))
            .isInstanceOf(UnsupportedOperationException.class);  // unmodifiable!
    }
}
